   "answer": 0,
   "explain": "】目的对应。题干逻辑关系：猛药去疴指用猛药医治重病缠身的人，形容事情的严重 性与危急性；重典治乱是指在乱世，需要刑法很重的法律来治，猛药的目的是去疴，重 典的目的是治乱，二者为目的对应关系 A 项，静以修身是指依靠内心安静精力集中来修养身心，俭以养德是指依靠俭朴的作风 来培养品德，静的目的是修身，俭的目的是养德，二者为目的对应关系，与题干逻 辑关系一致，当选； 31 全国服务热线：400-6353-606 B 项，名非天造，必从其实是指事物的各种客观名称、名义不是想当然地凭空生成的，它 必定是从事物的客观实践情况中得出来的，与题干逻辑关系不一致，排除； C 项，民生在勤，勤则不匮是指民众的生计、生活在于勤劳，勤劳就不会出现物资匮乏， 二者是因果对应关系，与题干逻辑关系不一致，排除； D 项，从善如登是指向好发展就像登山一样艰难，从恶如崩是指向坏发展就像山崩一样 迅速。二者是并列关系，与题干",
