   "module": "changshi",
   "q": "党的二十大报告指出，从现在起，党中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。下列对中国式现代化的理解，正确的有几项（ ）①坚持把实现人民对美好生活的向往作为现化化建设的出发点和落脚点②共同富裕是社会主义的本质要求，是中国式现代化的重要特征③在物质文明方面超越西方发达国家，是中国式现代化的主要目标④遵循世界各国现代化的共同模式，是中国式现代化道路的基本经验⑤中国式现代化新道路，创造了人类文明新形态",
