   "q": "党的二十大报告指出，要发展全过程人民民主，保障人民当家作主。关于人民民主，下列表述正确的是（ ）①人民民主是社会主义的生命，是全面建设现代化国家的应有之义②全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主~ 1 ~全国服务电话：400-6353-606③协商民主是实践全过程人民民主的重要形式④党内民主是全过程人民民主的重要体现",
