   "answer": 2,
   "explain": "】本题考查人文常识。 A 项，正确，皮洛遗址地处青藏高原，位于四川省甘孜藏族自治州稻城县，是迄今青藏高 原上发现的规模最大、保存最完整的旧石器时代遗址； B 项，正确，郑家湖墓地是秦汉时期墓葬，位于湖北省云梦县，分布于楚王城城址的东南 郊，西距龙岗墓地约1000 米、睡虎地墓地约3000 米； C 项，错误，山东滕州岗上遗址以大汶口文化中晚期为主； D 项，正确，明中都是明太祖朱元璋在家乡凤阳兴建的都城。 故正确答案为C。",
