   "explain": "】近义关系。题干逻辑关系：一望无垠是只辽阔看不到边际，与辽阔属于近义词。 A 项，方兴未艾指事物还在蓬勃发展与失败无明显逻辑关系，与题干逻辑关系不一致， 排除； B 项，厉兵秣马是指做好战斗准备，与战斗不是近义词，与题干逻辑关系不一致，排除； C 项，人云亦云指没有主见，只会附和，与重复无明显逻辑关系，与题干逻辑关系不一 致，排除； D 项，耳提面命形容对人教会恳切与教导属于近义词，与题干逻辑关系一致，当选。 35 全国服务热线：400-6353-606 故正确答案为D。",
