   "q": "2021 年下半年，我国固定互联网宽带接入用户中，光纤用户数增量超过500 万户的月份有几个（ ）",
   "options": [
    "2",
    "3",
    "4",
    "5"
   ],
   "answer": 0,
   "explain": "】增长量相关。根据表格材料可知2021 年6—12 月光纤用户数量。根据公式：增长量 =现期量-基期量，可知2021 年7 月光纤用户数增量为48416 −47968 = 448万户，8 月 增长量为48921 −48416 = 505万户，9 月增长量为49643 −48921 = 722万户，10 月增 长量为50077 −49643 = 434万户，11 月增长量为50466 −50077 = 389万户，12 月增 42 全国服务热线：400-6353-606 长量为50551 −50466 = 85万户。故2021 年下半年，我国固定互联网宽带接入用户中， 光纤用户数增量超过500 万户的月份有8 月、9 月，共2 个月份。 故正确答案为A。",
