   "module": "changshi",
   "q": "关于个人信息保护，下列说法不符合我国法律规定的是（ ）",
   "options": [
    "通过自动化决策方式向个人进行商业营销，应同时提供不针对其个人特征的选项或便~ 2 ~全国服务电话：400-6353-606捷的拒绝方式",
    "通过人脸识别技术所收集的个人图像、身份识别信息只能用于维护公共安全目的",
    "个人信息和隐私有密切的关系，个人信息当中的私密信息适用有关隐私权的规定",
    "用户量巨大的个人信息处理者需要定期发布个人信息保护社会责任报告"
   ],
   "answer": 1,
   "explain": "】本题考查法律常识。 A 项，根据《个人信息保护法》第二十四条第二款规定，通过自动化决策方式向个人进行 信息推送、商业营销，应当同时提供不针对其个人特征的选项，或者向个人提供便 捷的拒绝方式； B 项，根据《个人信息保护法》第二十六条规定，在公共场所安装图像采集、个人身份识 别设备，应当为维护公共安全所必需，遵守国家有关规定，并设置显著的提示标识。 所收集的个人图像、身份识别信息只能用于维护公共安全的目的，不得用于其他目 的；取得个人单独同意的除外； C 项，根据《民法典》第一千零三十四条规定，个人信息中的私密信息，适用有关隐私权 的规定；没有规定的，适用有关个人信息保护的规定； D 项，根据《个人信息保护法》第五十八条规定，提供重要互联网平台服务、用户数量巨 大、业务类型复杂的个人信息处理者，应当履行下列义务：（一）按照国家规定建立 健全个人信息保护合规制度体系，成立主要由外部成员组成的",
