   "module": "changshi",
   "q": "根据《中华人民共和国噪声污染防治法》，下列噪声污染情形与作出责令改正或处罚决定的主体对应错误的是（ ）",
   "options": [
    "甲企业在噪声敏感建筑物集中区域改建厂房造成工业噪声污染——住房和城乡建设部门",
    "乙企业无排污许可证排放工业噪声——生态环境主管部门",
    "丙商场在促销时持续使用高音广播喇叭发出噪声——地方人民政府指定的部门",
    "丁驾驶拆除消声器的机动车轰鸣行驶——公安机关交通管理部门"
   ],
   "answer": 0,
   "explain": "】本题考查法律常识。根据《中华人民共和国噪声污染防治法》第七十四条的规定， 违反本法规定，在噪声敏感建筑物集中区域新建排放噪声的工业企业的，由生态环境主 管部门责令停止违法行为，处十万元以上五十万元以下的罚款，并报经有批准权的人民 政府批准，责令关闭。违反本法规定，在噪声敏感建筑物集中区域改建、扩建工业企业， 未采取有效措施防止工业噪声污染的，由生态环境主管部门责令改正，处十万元以上五 十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令关闭。 5 全国服务热线：400-6353-606 故正确答案为A。",
