   "module": "changshi",
   "q": "下列与交通安全有关的说法错误的是（ ）",
   "options": [
    "机动车载运放射性危险物品应当经公安机关批准后按指定的时间、路线、速度行驶",
    "在允许拖拉机通行的道路上，拖拉机可以从事货运，但是不得用于载人",
    "行人故意碰撞机动车造成交通事故的，机动车一方承担次要责任",
    "前车为执行紧急任务的救护车、工程救险车的，后车不得超车"
   ],
   "answer": 2,
   "explain": "】本题考查法律常识。根据《中华人民共和国道路交通安全法》第七十六条的规定， 交通事故的损失是由非机动车驾驶人、行人故意碰撞机动车造成的，机动车一方不承担 赔偿责任。 故正确答案为C。",
   "year": 2023,
   "exam_type": "gk-xzf",
   "exam_volume": "行测",
