   "answer": 1,
   "explain": "】工程问题。已知甲单独完成时间及乙丙合作完成时间，判定为给定时间的工程问 题，故赋值时间最小公倍数12 为工作总量。假设甲乙合作时间为x，则乙单独工作时间 12 为x + 4。可求出甲乙合作效率为 x ，乙的效率可表示为 的效率为2，则丙的效率为1。丙单独工作所需时间为 故正确答案为B。",
