   "module": "shuliang",
   "q": "某单位有甲和乙两个办公室，分别有职工5 人和4 人。每周从这9 名职工中随机抽取1人下沉社区担任志愿者（同一人有可能被连续、重复选中）。问七月前2 周的志愿者均来自甲办公室的概率在以下哪个范围内（ ）",
