   "explain": "】概率问题。由题意可知每周从9 名职工中抽取1 人，且可以重复，则总情况数为： 1 × C9 1＝81种，前两周的志愿者均来自甲办公室的情况数为：C5 1 × C5 1＝25种，根据概率 C9 满足条件的情况数 ＝ 总的情况数 ，则前两周的志愿者均来自甲办公室的概率为： 故正确答案为B。",
