   "module": "ziliao",
   "q": "将①美国、②东盟十国、③欧盟27 国和④日本按2021 年中国进口纺织品服装金额同比增量从高到低排列，以下正确的是（ ）",
   "options": [
    "①②③④",
    "①②④③",
    "②①③④",
    "②①④③"
   ],
   "answer": 3,
   "explain": "】增长量比大小。根据材料第二段：美国出口额为563．5 亿美元，同比增长4．0%； 向东盟十国出口纺织品服装491.2 亿美元，同比增长24.9%；对欧盟27 国出口纺织品服 装469.9 亿美元，同比下降11.1%;对日本出口纺织品服装200.3 亿美元，同比下降7.2%。 则增长量可用现期量×增长率进行大小比较美国与东盟现期量接近，增长率之间有明显 倍数关系，故东盟增长量>美国。日本及欧盟增长率接近但现期量之间有明显倍数关系， 故欧盟增长量的绝对值大于日本，即日本增长量大于欧盟。 故正确答案为D。",
